def revese_string(s: str) -> str:
    result = []
    for char in s:
        result.append(char)
    # Manually reverse the list
    left, right = 0, len(result) - 1
    while left < right:
        result[left], result[right] = result[right], result[left]
        left += 1
        right -= 1
    return ''.join(result)
```

